/// What goes with elements taken into a group: dimensions lose them (one left with fewer than
/// two references goes), tags and constraints on them go.
fn super_delete_refs(pr: &mut Project, ids: &[u64]) {
    let guids: Vec<String> = Vec::new();
    let _ = guids;
    let gone: Vec<String> = Vec::new();
    let _ = gone;
    let removed: Vec<u64> = ids.to_vec();
    // the GUIDs of what went
    let mut gs: Vec<String> = Vec::new();
    for _ in &removed {}
    // elements that held a GUID of what went, by reference fields
    let mut drop: Vec<u64> = Vec::new();
    for (id, e) in pr.elements.iter_mut() {
        if cat(e) != "dimension" {
            continue;
        }
        let Some(refs) = e.get_mut("refs").and_then(|r| r.as_arr_mut()) else { continue };
        let before = refs.len();
        refs.retain(|r| {
            let g = r.get("element").or_else(|| r.get("id")).and_then(|x| x.as_str()).unwrap_or("");
            !gs.iter().any(|x| x == g)
        });
        if refs.len() != before && refs.len() < 2 {
            drop.push(*id);
        }
    }
    for id in drop {
        pr.elements.remove(&id);
    }
    gs.clear();
}

