cases = [((-1, 28), 27018.48859789625), ((-3, 19), 6082.540365447424), ((-3, 7), 2232.2093586152832), ((10, 3), 3160.8267412298), ((1, 1), 707.1067811865477), ((-1, 1), 707.1067811865474), ((-5,22), None)]
def sols(i, j, rng=40):
    out = []
    for c in range(-rng, rng+1):
        for d in range(-rng, rng+1):
            if i*d - j*c == 1:
                out.append((c, d))
    return out
def fmod_pos(x, l):
    r = math.fmod(x, l)
    if r < 0: r += l
    return r
for (i, j), exp in cases:
    if exp is None: continue
    L = math.hypot(i*W, j*H)
    ux, uy = i*W/L, j*H/L
    res = {}
    for c, d in sols(i, j):
        vals = {
            'dot_u': (c*W)*ux + (d*H)*uy,
            'dot_div': ((c*W)*(i*W) + (d*H)*(j*H))/L,
            'int_div': (c*i*W*W + d*j*H*H)/L,
        }
        for k, v in vals.items():
            for mk, m in [('fmodpos', fmod_pos(v, L)), ('raw', v), ('sub', v - math.floor(v/L)*L)]:
                if m == exp:
                    res.setdefault((k, mk), []).append((c, d))
    print((i, j), exp, res)

