import math
W = H = 1000.0
cases = [((-1, 28), 27018.48859789625), ((-3, 19), 6082.540365447424), ((-3, 7), 2232.2093586152832), ((10, 3), 3160.8267412298), ((1, 1), 707.1067811865477), ((-1, 1), 707.1067811865474)]
def sols(i, j, rng=60):
    out = []
    for c in range(-rng, rng+1):
        for d in range(-rng, rng+1):
            if i*d - j*c == 1:
                out.append((c, d))
    return out
def fmod_pos(x, l):
    r = math.fmod(x, l)
    if r < 0: r += l
    return r
def rem_euclid(x, l):
    r = x % l  # python's mod is floor-based
    return r
found = {}
