                v = (c*W)*ux + (d*H)*uy
                for mk, m in [('fmodpos', fmod_pos(v, LL)), ('raw', v), ('pymod', rem_euclid(v, LL)), ('sub', v - math.floor(v/LL)*LL)]:
                    if m == exp:
                        found.setdefault((un, Ln, mk), set()).add((i, j))
for k, v in found.items():
