import math, itertools
W = H = 1000.0
cases = [((-1, 28), 27018.48859789625), ((-3, 19), 6082.540365447424), ((-3, 7), 2232.2093586152832), ((10, 3), 3160.8267412298), ((1, 1), 707.1067811865477), ((-1, 1), 707.1067811865474)]
def sols(i, j, rng=60):
    return [(c, d) for c in range(-rng, rng+1) for d in range(-rng, rng+1) if i*d - j*c == 1]
def frac(x): return x - math.floor(x)
found = {}
for (i, j), exp in cases:
    L = math.hypot(i*W, j*H)
    LL = (i*W)**2 + (j*H)**2
    for c, d in sols(i, j):
        dot = (c*W)*(i*W) + (d*H)*(j*H)
        forms = {
            'L*frac(dot/LL)': L*frac(dot/LL),
            'frac(dot/LL)*L': frac(dot/LL)*L,
            'L*frac(dot/(L*L))': L*frac(dot/(L*L)),
            'frac(dot/L/L)*L': frac(dot/L/L)*L,
            'dot/L fmod': math.fmod(dot/L, L) + (L if math.fmod(dot/L, L) < 0 else 0),
            'L*frac(int)': L*frac((c*i+d*j)/(i*i+j*j)) if W == H else 0,
            'frac(int)*L': frac((c*i+d*j)/(i*i+j*j))*L if W == H else 0,
        }
        for k, v in forms.items():
            if v == exp:
                found.setdefault(k, set()).add((i, j))
for k, v in sorted(found.items(), key=lambda x: -len(x[1])):
    print(k, len(v), sorted(v))

