import math, itertools
W = H = 1000.0
cases = [((-1, 28), 27018.48859789625), ((-3, 19), 6082.540365447424), ((-3, 7), 2232.2093586152832), ((10, 3), 3160.8267412298), ((1, 1), 707.1067811865477), ((-1, 1), 707.1067811865474)]
def eg_rec(a, b):
    if b == 0: return (a, 1, 0)
    g, x, y = eg_rec(b, a % b)  # python floor mod
    return (g, y, x - (a // b) * y)
def eg_trunc(a, b):
    # rust-like truncated division
    if b == 0: return (a, 1, 0)
    q = int(a / b); r = a - q*b
    g, x, y = eg_trunc(b, r)
    return (g, y, x - q*y)
def eg_iter(a, b):
    old_r, r = a, b; old_s, s = 1, 0; old_t, t = 0, 1
    while r != 0:
        q = int(old_r / r)
        old_r, r = r, old_r - q*r
        old_s, s = s, old_s - q*s
        old_t, t = t, old_t - q*t
    return (old_r, old_s, old_t)
def choices(i, j):
    out = {}
    for name, eg in [('rec', eg_rec), ('trunc', eg_trunc), ('iter', eg_iter)]:
        # want i*d - j*c = 1
        for argn, (a, b, mapf) in {
            'i,-j': (i, -j, lambda g, x, y: (y, x)),
            'i,j': (i, j, lambda g, x, y: (-y, x)),
            '|i|,|j|': (abs(i), abs(j), None),
            'j,i': (j, i, lambda g, x, y: (-x, y)),
        }.items():
            g, x, y = eg(a, b)
            if mapf is None:
                # abs version: |i| x + |j| y = g -> i (sx x) + j (sy y) = g
                sx = 1 if i >= 0 else -1; sy = 1 if j >= 0 else -1
                d, c = sx*x, -sy*y
            else:
                c, d = mapf(g, x, y)
            if i*d - j*c == -1:
                c, d = -c, -d
            if i*d - j*c == 1:
                out[name + ':' + argn] = (c, d)
    return out
def frac(x): return x - math.floor(x)
def fmodpos(x, l):
    r = math.fmod(x, l)
    return r + l if r < 0 else r
def forms(i, j, c, d):
    L = math.hypot(i*W, j*H)
    ux, uy = i*W/L, j*H/L
    dot = (c*W)*(i*W) + (d*H)*(j*H)
    v = (c*W)*ux + (d*H)*uy
    return {
        'dotu fmodpos': fmodpos(v, L),
        'dotu pymod': v % L,
        'dotu sub': v - math.floor(v/L)*L,
        'L*frac(dot/(L*L))': L*frac(dot/(L*L)),
        'frac(dot/L/L)*L': frac(dot/L/L)*L,
        'frac(v/L)*L': frac(v/L)*L,
        'L*frac(v/L)': L*frac(v/L),
        'dot/L fmodpos': fmodpos(dot/L, L),
        'dot/L pymod': (dot/L) % L,
    }
res = {}
for (i, j), exp in cases:
    for cn, (c, d) in choices(i, j).items():
        for fn, v in forms(i, j, c, d).items():
            res.setdefault((cn, fn), []).append(v == exp)
for k, v in sorted(res.items(), key=lambda x: -sum(x[1])):
    if sum(v) >= 5: print(k, sum(v), v)

