def fmodpos(x, l):
    r = math.fmod(x, l)
    return r + l if r < 0 else r
def frac(x): return x - math.floor(x)
forms = {}
def F(name):
    def deco(f):
        forms[name] = f
        return f
    return deco
@F('a')
def _(c, d, i, j, W, H, L): return fmodpos((c*W)*((i*W)/L) + (d*H)*((j*H)/L), L)
@F('inv')
def _(c, d, i, j, W, H, L):
    k = 1.0/L
    return fmodpos(((c*W)*(i*W) + (d*H)*(j*H))*k, L)
@F('uinv')
def _(c, d, i, j, W, H, L):
    k = 1.0/L
    return fmodpos((c*W)*(i*W*k) + (d*H)*(j*H*k), L)
@F('cosdeg')
def _(c, d, i, j, W, H, L):
    a = math.radians(math.degrees(math.atan2(j*H, i*W)))
    return fmodpos((c*W)*math.cos(a) + (d*H)*math.sin(a), L)
@F('cosrad')
def _(c, d, i, j, W, H, L):
    a = math.atan2(j*H, i*W)
    return fmodpos((c*W)*math.cos(a) + (d*H)*math.sin(a), L)
@F('fracL')
def _(c, d, i, j, W, H, L):
    t = ((c*W)*(i*W) + (d*H)*(j*H))/(L*L)
    return frac(t)*L
@F('fracL2')
def _(c, d, i, j, W, H, L):
    t = (c*i*W*W + d*j*H*H)/(i*i*W*W + j*j*H*H)
    return frac(t)*L
@F('fracL3')
def _(c, d, i, j, W, H, L):
    t = (c*i*W*W + d*j*H*H)/(i*i*W*W + j*j*H*H)
    return L*frac(t)
@F('fracint')
def _(c, d, i, j, W, H, L):
    num = c*i*W*W + d*j*H*H
    den = i*i*W*W + j*j*H*H
    return (math.fmod(num, den) + (den if math.fmod(num, den) < 0 else 0))/den*L
@F('fracint2')
def _(c, d, i, j, W, H, L):
    num = c*i*W*W + d*j*H*H
    den = i*i*W*W + j*j*H*H
    r = math.fmod(num, den)
    if r < 0: r += den
    return r/L
@F('fracint3')
def _(c, d, i, j, W, H, L):
    num = c*i*W*W + d*j*H*H
    den = L*L
    r = math.fmod(num, den)
    if r < 0: r += den
    return r/L
res = {}
for ((i, j), W, H), exp in uniq.items():
    L = math.hypot(i*W, j*H)
    g, x, y = eg_trunc(i, j)
    if g < 0: x, y = -x, -y
    c0, d0 = -y, x
    for fn, f in forms.items():
