fn overlap(s: &Seg, t: &Seg) -> bool {
    let d = [s.b[0] - s.a[0], s.b[1] - s.a[1]];
    let l = (d[0] * d[0] + d[1] * d[1]).sqrt();
    if l == 0.0 {
        return false;
