new = '''/// A cubic spline through the points by their chords' lengths: natural at its ends, or leaving
/// and reaching them along the tangents given. Each piece: its ends, their second derivatives,
/// its parameter's length.
fn fit_pieces(fit: &[P], t0: Option<P>, t1: Option<P>) -> Vec<(P, P, P, P, f64)> {
    let n = fit.len();
    let mut out = Vec::new();
    if n < 2 {
        return out;
    }
    let h: Vec<f64> = (0..n - 1).map(|i| hypot2([fit[i + 1][0] - fit[i][0], fit[i + 1][1] - fit[i][1]])).collect();
    if h.iter().any(|x| *x == 0.0) {
        return out;
    }
    let unit = |t: Option<P>| -> Option<P> {
        let t = t?;
        let l = hypot2(t);
        if l == 0.0 {
            None
        } else {
            Some([t[0] / l, t[1] / l])
        }
    };
    let u0 = unit(t0);
    let u1 = unit(t1);
    let mut second: Vec<P> = vec![[0.0, 0.0]; n];
    for dim in 0..2 {
        let y: Vec<f64> = fit.iter().map(|p| p[dim]).collect();
        let mut a = vec![0.0; n];
        let mut b = vec![0.0; n];
        let mut c = vec![0.0; n];
        let mut d = vec![0.0; n];
        match u0 {
            Some(u) => {
                b[0] = 2.0 * h[0];
                c[0] = h[0];
                d[0] = 6.0 * ((y[1] - y[0]) / h[0] - u[dim]);
            }
            None => b[0] = 1.0,
        }
        for i in 1..n - 1 {
            a[i] = h[i - 1];
            b[i] = 2.0 * (h[i - 1] + h[i]);
            c[i] = h[i];
            d[i] = 6.0 * ((y[i + 1] - y[i]) / h[i] - (y[i] - y[i - 1]) / h[i - 1]);
        }
        match u1 {
            Some(u) => {
                a[n - 1] = h[n - 2];
                b[n - 1] = 2.0 * h[n - 2];
                d[n - 1] = 6.0 * (u[dim] - (y[n - 1] - y[n - 2]) / h[n - 2]);
            }
            None => b[n - 1] = 1.0,
        }
        // the Thomas algorithm
        let mut cp = vec![0.0; n];
        let mut dp = vec![0.0; n];
        cp[0] = c[0] / b[0];
        dp[0] = d[0] / b[0];
        for i in 1..n {
            let m = b[i] - a[i] * cp[i - 1];
            cp[i] = if i < n - 1 { c[i] / m } else { 0.0 };
            dp[i] = (d[i] - a[i] * dp[i - 1]) / m;
        }
        let mut m = vec![0.0; n];
        m[n - 1] = dp[n - 1];
        for i in (0..n - 1).rev() {
            m[i] = dp[i] - cp[i] * m[i + 1];
        }
        for i in 0..n {
            second[i][dim] = m[i];
