/// How many chords a whole circle of radius `r` is drawn with.
pub fn circle_segments(r: f64) -> usize {
    let n_sag = (std::f64::consts::TAU / sag_step(r)).ceil();
    let k = five_degree_steps(r);
    let n_min = (72.0 / k).floor();
    let n = n_sag.max(n_min).max(3.0);
    if !n.is_finite() || n > MAX_POINTS as f64 {
        MAX_POINTS
    } else {
        n as usize
    }
}

/// How many chords an arc of radius `r` turning `sweep` radians is drawn with.
pub fn arc_segments(r: f64, sweep: f64) -> usize {
    let s = sweep.abs();
    let n_sag = (s / sag_step(r)).ceil();
    let k = five_degree_steps(r);
    let step = 5f64.to_radians();
    let n_min = if k <= 1.0 { (s / step).ceil() } else { (s / (k * step)).round() };
    let n = n_sag.max(n_min).max(1.0);
    if !n.is_finite() || n > MAX_POINTS as f64 {
        MAX_POINTS
    } else {
        n as usize
    }
