fn segments(r: f64, sweep: f64) -> usize {
    let s = sweep.abs();
    let n = (s / sag_step(r)).ceil().max((s / 5f64.to_radians()).ceil()).max(1.0);
    if !n.is_finite() || n > MAX_POINTS as f64 {
        MAX_POINTS
    } else {
        n as usize
    }
}

