import sys, math, json, itertools
sys.path.insert(0, '/tmp/views-groups')
from tess import tess_raw
def get(a, b, t):
    p = tess_raw([{"start":list(a),"end":list(b),"arc":t},[list(b),list(a)]])
    if p[0] != list(a):
        i = p.index(list(a)); p = p[i:] + p[:i]
    if p[1] == list(b):
        p = [p[0]] + list(reversed(p[1:]))
    return p
cases = [((0.0, 0.0), (1000.0, 0.0), 90.0), ((100.0, 0.0), (0.0, 100.0), 90.0), ((0.0, 0.0), (1000.0, 0.0), 120.0), ((10.0, 20.0), (110.0, 120.0), -90.0), ((0.0,0.0),(1000.0,0.0),-50.0), ((0.0,0.0),(1000.0,0.0),33.0)]
data = [(a, b, t, get(a, b, t)) for a, b, t in cases]
def centre_forms(a, b, th):
    dx, dy = b[0]-a[0], b[1]-a[1]
    c = math.hypot(dx, dy)
    m = ((a[0]+b[0])/2, (a[1]+b[1])/2)
    m2 = (a[0] + dx/2, a[1] + dy/2)
    out = {}
    for mn, mm in [('m', m), ('m2', m2)]:
        k = 0.5/math.tan(th/2)
        out[mn+'v3'] = (mm[0]-dy*k, mm[1]+dx*k)
        k2 = (c/2)/math.tan(th/2)
        out[mn+'cot'] = (mm[0]-dy/c*k2, mm[1]+dx/c*k2)
        out[mn+'cot2'] = (mm[0]+(-dy/c)*k2, mm[1]+(dx/c)*k2)
        out[mn+'cot3'] = (mm[0]-dy*(k2/c), mm[1]+dx*(k2/c))
        r = c/(2*abs(math.sin(th/2)))
        h = r*math.cos(th/2)*(1 if th > 0 else -1)
        out[mn+'rh'] = (mm[0]-dy/c*h, mm[1]+dx/c*h)
        hs = math.sqrt(r*r - (c/2)**2)*(1 if th > 0 else -1)*(1 if abs(th) < math.pi else -1)
        out[mn+'sq'] = (mm[0]-dy/c*hs, mm[1]+dx/c*hs)
    return out
res = {}
for a, b, t, p in data:
    n = len(p) - 1
    th = math.radians(t)
    dx, dy = b[0]-a[0], b[1]-a[1]
    c = math.hypot(dx, dy)
    rads = {'c/2sin': c/(2*abs(math.sin(th/2))), 'c2/sin': (c/2)/abs(math.sin(th/2))}
    for cn, cen in centre_forms(a, b, th).items():
        rads2 = dict(rads)
        rads2['|a-c|'] = math.hypot(a[0]-cen[0], a[1]-cen[1])
        for rn, r in rads2.items():
            a0 = math.atan2(a[1]-cen[1], a[0]-cen[0])
            for sn, S in [('th', th), ('L/r', (r*abs(th))/r*(1 if th > 0 else -1))]:
                for fn in [0, 1, 2]:
                    ok = 0
