                        if fn == 0: ang = a0 + S*k/n
                        elif fn == 1: ang = a0 + S*(k/n)
                        else: ang = a0 + k*(S/n)
                        q = [cen[0] + r*math.cos(ang), cen[1] + r*math.sin(ang)]
                        if q == p[k]: ok += 1
                    res.setdefault((cn, rn, sn, fn), []).append((ok, n - 1))
for k, v in sorted(res.items(), key=lambda x: -sum(o for o, _ in x[1]))[:8]:
    print(k, v, sum(o for o, _ in v), sum(t for _, t in v))

