1	//! Detail groups: `create_group`, `detail_group`, `repeating_detail`, `ungroup`, `group_type`.
2	//!
3	//! A group type is the file's `detail_groups.<name>`: `{members: [{id, guid, element}]}`, each
4	//! member a detail line, a filled region or a text note as an element of no view (`view: 0`),
5	//! about the middle of what was grouped, and a `detail-group` library entry. A placed group is
6	//! `{guid, category: "detailgroup", view, type, at, angle?, mirrored?}`; a repeating detail
7	//! `{guid, category: "repeatingdetail", view, type, start, end, spacing, mirrored?}`, one group
8	//! every `spacing` from `start` toward `end`, each turned along the line.
9	
10	use super::common::*;
11	use super::regions::curve::{self, Place, P};
12	use super::regions::{self, view_check, view_level, view_or_level};
13	use crate::json::{Map, Value};
14	use crate::project::Project;
15	use crate::session::Session;
16	
17	const KIND: &str = "detail-group";
18	const SECTION: &str = "detail_groups";
19	/// The most repeats a repeating detail places.
20	pub const MAX_REPEATS: u64 = 2000;
21	/// The most group members a view draws.
22	pub const MAX_PLACED: u64 = 10000;
23	
24	/// Runs the commands of this part.
25	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
26	    match cid {
27	        "create_group" => create_group(s, p),
28	        "detail_group" => detail_group(s, p),
29	        "repeating_detail" => repeating_detail(s, p),
30	        "ungroup" => ungroup(s, p),
31	        "group_type" => group_type(s, p),
32	        _ => Err(format!("{}: not supported here", cid)),
33	    }
34	}
35	
36	fn check_keys(p: &Value, cmd: &str, allowed: &[&str]) -> R<()> {
37	    crate::styles::common::check_keys(p, cmd, allowed)
38	}
39	
40	fn opt_name(p: &Value, cmd: &str, key: &str) -> R<Option<String>> {
41	    crate::styles::common::opt_name(p, cmd, key)
42	}
43	
44	// ---------------------------------------------------------------- the types
45	
46	/// The project's group types' names, in order.
47	pub fn type_names(pr: &Project) -> Vec<String> {
48	    let mut v: Vec<String> = pr.section(SECTION).map(|s| s.keys().cloned().collect()).unwrap_or_default();
49	    v.sort();
50	    v
51	}
52	
53	/// A type's members.
54	pub fn members(pr: &Project, name: &str) -> Vec<Value> {
55	    pr.section(SECTION)
56	        .and_then(|s| s.get(name))
57	        .and_then(|t| t.get("members"))
58	        .and_then(|m| m.as_arr())
59	        .cloned()
60	        .unwrap_or_default()
61	}
62	
63	/// The name of the group type a GUID names.
64	pub fn type_of_guid(pr: &Project, g: &str) -> Option<String> {
65	    regions::lib_kind_name(pr, KIND, g)
66	}
67	
68	/// The type a placed group or a repeating detail is of, by name.
69	pub fn type_name(pr: &Project, e: &Value) -> Option<String> {
70	    type_of_guid(pr, s_of(e, "type")?)
71	}
72	
73	fn type_guid(pr: &mut Project, name: &str) -> String {
74	    match pr.lib_guid(KIND, name) {
75	        Some(g) => g,
76	        None => pr.lib_add(KIND, name).1,
77	    }
78	}
79	
80	/// How many times a repeating detail places its group: one at `start` and one every `spacing`
81	/// on to `end`.
82	pub fn repeat_count(e: &Value) -> u64 {
83	    let a = pt_of(e, "start").unwrap_or([0.0, 0.0]);
84	    let b = pt_of(e, "end").unwrap_or([0.0, 0.0]);
85	    let sp = f_of(e, "spacing").unwrap_or(0.0);
86	    let l = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
87	    if !(sp > 0.0) {
88	        return 1;
89	    }
90	    let n = (l / sp).floor();
91	    if !n.is_finite() || n >= 1e15 {
92	        return u64::MAX / 2;
93	    }
94	    n as u64 + 1
95	}
96	
97	// ---------------------------------------------------------------- elements, by id or GUID
98	
99	fn not_an_id(cmd: &str, v: &Value) -> String {
100	    format!("{}: {} is not an element id or GUID", cmd, v.to_compact())
101	}
102	
103	/// An element by its id (a number, or one in a string) or its GUID.
104	pub fn element_ref(pr: &Project, cmd: &str, v: &Value) -> R<u64> {
105	    match v {
